# region: sql.py
"""Shared SQL helpers for dual-run comparison templates."""



_UC_FQN = re.compile(r"^[`']?[\w-]+[`']?\.[`']?[\w-]+[`']?\.[`']?[\w-]+[`']?$")
_CLOUD_PATH = re.compile(
    r"^(?:dbfs:/|s3a?://|gs://|wasbs?://|abfss?://|adl://|file:///)[^\s`]+$",
    re.IGNORECASE,
)


def detect_ref_kind(ref: str) -> str:
    cleaned = ref.strip().strip("`")
    if _UC_FQN.match(cleaned):
        return "table"
    if _CLOUD_PATH.match(cleaned):
        return "path"
    if re.match(r"^[\w-]+$", cleaned):
        return "table"
    raise ValueError(f"unsupported compare ref: {ref!r}")


def table_expr(ref: str) -> str:
    """Spark SQL table expression for FQN or delta path."""
    if detect_ref_kind(ref) == "table":
        return ref.strip().strip("`")
    return f"delta.`{ref.strip()}`"


def describe_table_sql(ref: str) -> str:
    return f"DESCRIBE TABLE {table_expr(ref)}"


def describe_detail_sql(ref: str) -> str:
    return f"DESCRIBE DETAIL {table_expr(ref)}"


def describe_history_sql(ref: str, limit: int = 100) -> str:
    return f"DESCRIBE HISTORY {table_expr(ref)} LIMIT {limit}"


def count_sql(ref: str) -> str:
    return f"SELECT COUNT(*) AS row_count FROM {table_expr(ref)}"


def pair_context_comment(pair_label: str, check_id: str) -> str:
    return f"# Compare pair={pair_label!r} check={check_id}"
# endregion: sql.py

