def pair_to_dict(pair: ComparePair) -> dict[str, Any]:
    data = asdict(pair)
    return {k: v for k, v in data.items() if v is not None}


def config_to_dict(config: CompareConfig) -> dict[str, Any]:
    """Serialize CompareConfig to a JSON/YAML-friendly dict."""

    def _tolerance(t: NumericTolerance) -> dict[str, float]:
        return {"absolute": t.absolute, "relative_percent": t.relative_percent}

    tolerances = {
        k: _tolerance(v) for k, v in config.comparison_rules.numeric_tolerances.items()
    }
    return {
        "enabled": config.enabled,
        "report": asdict(config.report),
        "row_details": asdict(config.row_details),
        "comparison_rules": {
            "fail_on_duplicate_keys": config.comparison_rules.fail_on_duplicate_keys,
            "ignored_columns": config.comparison_rules.ignored_columns,
            "sensitive_columns": config.comparison_rules.sensitive_columns,
            "numeric_tolerances": tolerances,
            "timestamp_tolerance_seconds": config.comparison_rules.timestamp_tolerance_seconds,
        },
        "checks": asdict(config.checks),
        "filters": asdict(config.filters),
        "runtime": asdict(config.runtime),
        "numeric_columns": config.numeric_columns,
    }
