# region: config_bridge.py
"""Map compare config dicts to CompareConfig."""





def _numeric_tolerances(data: dict[str, Any] | None) -> dict[str, NumericTolerance]:
    if not data:
        return {}
    result: dict[str, NumericTolerance] = {}
    for key, val in data.items():
        if isinstance(val, dict):
            result[key] = NumericTolerance(
                absolute=float(val.get("absolute", 0.0)),
                relative_percent=float(val.get("relative_percent", 0.0)),
            )
        else:
            result[key] = NumericTolerance()
    return result


def compare_config_from_dict(data: dict[str, Any] | None) -> CompareConfig:
    if not data:
        return CompareConfig()

    report_data = data.get("report") or {}
    row_details_data = data.get("row_details") or {}
    rules_data = data.get("comparison_rules") or data
    checks_data = data.get("checks") or {}
    filters_data = data.get("filters") or {}
    runtime_data = data.get("runtime") or {}

    report = ReportConfig(
        root_uri=str(report_data.get("root_uri", ReportConfig.root_uri)),
        summary_json=bool(report_data.get("summary_json", True)),
        summary_markdown=bool(report_data.get("summary_markdown", True)),
        summary_html=bool(report_data.get("summary_html", False)),
        detail_format=str(report_data.get("detail_format", "delta")),
        write_audit_tables=bool(report_data.get("write_audit_tables", True)),
        audit_catalog=str(report_data.get("audit_catalog", "migration_audit")),
        audit_schema=str(report_data.get("audit_schema", "dualrun")),
    )

    row_details = RowDetailsConfig(
        enabled=bool(row_details_data.get("enabled", True)),
        max_issue_rows_per_table=row_details_data.get("max_issue_rows_per_table"),
        max_sample_rows_in_summary=int(row_details_data.get("max_sample_rows_in_summary", 100)),
        include_full_row_json=bool(row_details_data.get("include_full_row_json", True)),
        include_column_diff_json=bool(row_details_data.get("include_column_diff_json", True)),
        include_mismatch_columns=bool(row_details_data.get("include_mismatch_columns", True)),
        max_json_length=int(row_details_data.get("max_json_length", 100_000)),
    )

    ignored = rules_data.get("ignored_columns")
    if ignored is None and "ignore_technical_columns" in data:
        ignored = data.get("ignore_technical_columns")

    comparison_rules = ComparisonRulesConfig(
        fail_on_duplicate_keys=bool(
            rules_data.get("fail_on_duplicate_keys", data.get("fail_on_duplicate_keys", True))
        ),
        ignored_columns=list(ignored) if ignored is not None else ComparisonRulesConfig().ignored_columns,
        sensitive_columns=list(rules_data.get("sensitive_columns") or []),
        numeric_tolerances=_numeric_tolerances(rules_data.get("numeric_tolerances")),
        timestamp_tolerance_seconds=int(rules_data.get("timestamp_tolerance_seconds", 0)),
    )

    enable_status = checks_data.get("enable_distribution_by_status")
    if enable_status is None:
        enable_status = data.get("enable_distribution_by_status", False)

    checks = ChecksConfig(
        enable_basic_stats=bool(checks_data.get("enable_basic_stats", True)),
        enable_null_stats=bool(checks_data.get("enable_null_stats", True)),
        enable_distinct_stats=bool(checks_data.get("enable_distinct_stats", True)),
        enable_numeric_stats=bool(checks_data.get("enable_numeric_stats", True)),
        enable_datetime_stats=bool(checks_data.get("enable_datetime_stats", True)),
        enable_distribution_stats=bool(checks_data.get("enable_distribution_stats", True)),
        enable_row_comparison=bool(checks_data.get("enable_row_comparison", True)),
        enable_delta_operation_metrics=bool(checks_data.get("enable_delta_operation_metrics", True)),
        enable_delta_version_stats=bool(checks_data.get("enable_delta_version_stats", True)),
        enable_distribution_by_status=bool(enable_status),
    )

    filters = CompareFiltersConfig(
        business_date=filters_data.get("business_date"),
        where_clause=filters_data.get("where_clause"),
    )

    runtime = RuntimeConfig(
        fail_process_on=list(runtime_data.get("fail_process_on") or ["FAIL", "BLOCKED"]),
    )

    return CompareConfig(
        enabled=bool(data.get("enabled", True)),
        report=report,
        row_details=row_details,
        comparison_rules=comparison_rules,
        checks=checks,
        filters=filters,
        runtime=runtime,
        numeric_columns=data.get("numeric_columns"),
    )
