# region: renderers.markdown_renderer.py
"""Markdown report renderer for dual-run comparison."""




def render_summary_markdown(report: CompareRunReport) -> str:
    ctx = report.context
    counts = report.summary_counts
    lines = [
        "# Dual Run Comparison Report",
        "",
        "## Run Summary",
        "",
        "| Field | Value |",
        "|---|---|",
        f"| Dual Run ID | {ctx.dual_run_id} |",
        f"| Candidate | {ctx.candidate_id} |",
        f"| Project | {ctx.project_name} |",
        f"| Overall Severity | {report.overall_severity} |",
        f"| Compared Tables | {counts.get('compared_tables', 0)} |",
        f"| Failed Tables | {counts.get('failed_tables', 0)} |",
        f"| Total Row Issues | {counts.get('total_row_issues', 0)} |",
        "",
    ]

    for table in report.table_results:
        lines.extend(_render_table_section(table, report))

    row_issues = report.report_artifacts.get("row_issues", {})
    if row_issues:
        lines.extend(
            [
                "## Detail Dataset",
                "",
                "Unified row-level issues:",
                "",
                f"`{row_issues.get('path', '')}`",
                "",
            ]
        )
    return "\n".join(lines)


def _render_table_section(table: TableCompareResult, report: CompareRunReport) -> list[str]:
    lines = [
        f"## Table: {table.label}",
        "",
        "| Check Group | Severity | Notes |",
        "|---|---|---|",
    ]
    groups: dict[str, str] = {}
    for result in table.check_results:
        groups[result.check_group] = result.severity
    for group, severity in sorted(groups.items()):
        lines.append(f"| {group.title()} | {severity} | |")

    row_summary = table.row_summary or {}
    if row_summary:
        lines.extend(
            [
                "",
                "## Row Summary",
                "",
                "| Metric | Count |",
                "|---|---:|",
            ]
        )
        for key in (
            "matched_rows",
            "mismatched_rows",
            "missing_in_right",
            "extra_in_right",
            "duplicate_keys_left",
            "duplicate_keys_right",
            "hash_only_left",
            "hash_only_right",
            "hash_count_mismatch",
            "row_issues_count",
        ):
            if key in row_summary:
                lines.append(f"| {key.replace('_', ' ').title()} | {row_summary[key]} |")

    detail = table.detail_artifacts.get("row_issues", {})
    if detail:
        lines.extend(
            [
                "",
                "Filter:",
                "",
                "```sql",
                f"WHERE {detail.get('filter', '')}",
                "```",
                "",
            ]
        )
    return lines
# endregion: renderers.markdown_renderer.py

