# region: row_issues.py
"""Row comparison executor and unified row issue dataset builder."""





ROW_ISSUE_SCHEMA = StructType(
    [
        StructField("issue_id", StringType(), False),
        StructField("dual_run_id", StringType(), False),
        StructField("run_pair_id", StringType(), False),
        StructField("candidate_id", StringType(), False),
        StructField("project_name", StringType(), False),
        StructField("table_label", StringType(), False),
        StructField("left_ref", StringType(), False),
        StructField("right_ref", StringType(), False),
        StructField("left_table_version", LongType(), True),
        StructField("right_table_version", LongType(), True),
        StructField("issue_type", StringType(), False),
        StructField("issue_severity", StringType(), False),
        StructField("key_columns", ArrayType(StringType()), True),
        StructField("key_values_json", StringType(), True),
        StructField("row_hash", StringType(), True),
        StructField("left_row_hash", StringType(), True),
        StructField("right_row_hash", StringType(), True),
        StructField("mismatch_columns", ArrayType(StringType()), True),
        StructField("mismatch_count", IntegerType(), True),
        StructField("column_diff_json", StringType(), True),
        StructField("left_row_json", StringType(), True),
        StructField("right_row_json", StringType(), True),
        StructField("left_present", BooleanType(), True),
        StructField("right_present", BooleanType(), True),
        StructField("comparison_mode", StringType(), False),
        StructField("comparable_columns", ArrayType(StringType()), True),
        StructField("ignored_columns", ArrayType(StringType()), True),
        StructField("sample_only", BooleanType(), False),
        StructField("created_at", TimestampType(), False),
    ]
)


class RowCompareExecutor:
    def __init__(self, spark: SparkSession, config: CompareConfig):
        self.spark = spark
        self.config = config

    def execute(
        self,
        pair: ComparePair,
        context: CompareRunContext,
    ) -> tuple[CheckResult, DataFrame | None]:
        if pair.key_columns:
            return self.execute_key_based(pair, context)
        return self.execute_hash_based(pair, context)

    def execute_key_based(
        self,
        pair: ComparePair,
        context: CompareRunContext,
    ) -> tuple[CheckResult, DataFrame | None]:
        where = self.config.filters.where_clause
        left_df = read_table(self.spark, pair.left_ref, where)
        right_df = read_table(self.spark, pair.right_ref, where)
        comparable = resolve_comparable_columns(left_df, right_df, pair, self.config)
        keys = pair.key_columns or []
        ignored = list(
            set(self.config.comparison_rules.ignored_columns)
            | set(self.config.comparison_rules.sensitive_columns)
            | set(pair.ignored_columns or [])
        )

        left_h = add_row_hash(left_df, comparable, "left_row_hash")
        right_h = add_row_hash(right_df, comparable, "right_row_hash")

        dup_left = (
            left_h.groupBy(*keys).count().filter(F.col("count") > 1).count()
            if keys
            else 0
        )
        dup_right = (
            right_h.groupBy(*keys).count().filter(F.col("count") > 1).count()
            if keys
            else 0
        )

        left_dedup = left_h.dropDuplicates(keys) if keys else left_h
        right_dedup = right_h.dropDuplicates(keys) if keys else right_h

        join_cond = [left_dedup[k].eqNullSafe(right_dedup[k]) for k in keys]
        joined = left_dedup.alias("l").join(
            right_dedup.alias("r"), on=join_cond, how="full_outer"
        )

        missing = joined.filter(F.col("l.left_row_hash").isNotNull() & F.col("r.right_row_hash").isNull()).count()
        extra = joined.filter(F.col("l.left_row_hash").isNull() & F.col("r.right_row_hash").isNotNull()).count()
        matched = joined.filter(
            F.col("l.left_row_hash").isNotNull()
            & F.col("r.right_row_hash").isNotNull()
            & (F.col("l.left_row_hash") == F.col("r.right_row_hash"))
        ).count()
        mismatched = joined.filter(
            F.col("l.left_row_hash").isNotNull()
            & F.col("r.right_row_hash").isNotNull()
            & (F.col("l.left_row_hash") != F.col("r.right_row_hash"))
        ).count()

        metrics = {
            "comparison_mode": "key_based",
            "key_columns": keys,
            "matched_rows": matched,
            "mismatched_rows": mismatched,
            "missing_in_right": missing,
            "extra_in_right": extra,
            "duplicate_keys_left": dup_left,
            "duplicate_keys_right": dup_right,
            "row_issues_count": missing + extra + mismatched + dup_left + dup_right,
        }

        issues_df = self._build_key_issues(
            pair,
            context,
            left_h,
            right_h,
            joined,
            comparable,
            ignored,
            keys,
            dup_left,
            dup_right,
        )

        severity = evaluate_check_severity("key_based", metrics, self.config)
        return (
            CheckResult(
                check_id="key_based",
                check_group="rows",
                severity=severity,
                metrics=metrics,
            ),
            issues_df,
        )

    def execute_hash_based(
        self,
        pair: ComparePair,
        context: CompareRunContext,
    ) -> tuple[CheckResult, DataFrame | None]:
        where = self.config.filters.where_clause
        left_df = read_table(self.spark, pair.left_ref, where)
        right_df = read_table(self.spark, pair.right_ref, where)
        comparable = resolve_comparable_columns(left_df, right_df, pair, self.config)
        ignored = list(
            set(self.config.comparison_rules.ignored_columns)
            | set(self.config.comparison_rules.sensitive_columns)
            | set(pair.ignored_columns or [])
        )

        left_h = add_row_hash(left_df, comparable, "row_hash").groupBy("row_hash").agg(
            F.count("*").alias("left_count"),
            F.first(F.struct(*comparable)).alias("left_row"),
        )
        right_h = add_row_hash(right_df, comparable, "row_hash").groupBy("row_hash").agg(
            F.count("*").alias("right_count"),
            F.first(F.struct(*comparable)).alias("right_row"),
        )

        joined = left_h.alias("l").join(right_h.alias("r"), on="row_hash", how="full_outer")
        hash_only_left = joined.filter(
            F.col("l.row_hash").isNotNull() & F.col("r.row_hash").isNull()
        ).count()
        hash_only_right = joined.filter(
            F.col("l.row_hash").isNull() & F.col("r.row_hash").isNotNull()
        ).count()
        hash_count_mismatch = joined.filter(
            F.col("l.row_hash").isNotNull()
            & F.col("r.row_hash").isNotNull()
            & (F.col("l.left_count") != F.col("r.right_count"))
        ).count()
        hash_in_both = joined.filter(
            F.col("l.row_hash").isNotNull()
            & F.col("r.row_hash").isNotNull()
            & (F.col("l.left_count") == F.col("r.right_count"))
        ).count()

        metrics = {
            "comparison_mode": "hash_based",
            "hash_in_both": hash_in_both,
            "hash_only_left": hash_only_left,
            "hash_only_right": hash_only_right,
            "hash_count_mismatch": hash_count_mismatch,
            "row_issues_count": hash_only_left + hash_only_right + hash_count_mismatch,
        }

        issues_df = self._build_hash_issues(
            pair, context, joined, comparable, ignored, hash_only_left, hash_only_right, hash_count_mismatch
        )

        severity = evaluate_check_severity("hash_based", metrics, self.config)
        return (
            CheckResult(
                check_id="hash_based",
                check_group="rows",
                severity=severity,
                metrics=metrics,
            ),
            issues_df,
        )

    def _build_key_issues(
        self,
        pair: ComparePair,
        context: CompareRunContext,
        left_h: DataFrame,
        right_h: DataFrame,
        joined: DataFrame,
        comparable: list[str],
        ignored: list[str],
        keys: list[str],
        dup_left: int,
        dup_right: int,
    ) -> DataFrame | None:
        if not self.config.row_details.enabled:
            return None

        rows: list[dict[str, Any]] = []
        now = now(timezone.utc)
        max_json = self.config.row_details.max_json_length
        max_rows = self.config.row_details.max_issue_rows_per_table
        label = pair.pair_label()
        run_pair_id = f"{context.dual_run_id}:{label}"

        def add_issue(issue_type: str, **kwargs: Any) -> None:
            if max_rows is not None and len(rows) >= max_rows:
                return
            append(
                {
                    "issue_id": str(uuid.uuid4()),
                    "dual_run_id": context.dual_run_id,
                    "run_pair_id": run_pair_id,
                    "candidate_id": context.candidate_id,
                    "project_name": context.project_name,
                    "table_label": label,
                    "left_ref": pair.left_ref,
                    "right_ref": pair.right_ref,
                    "left_table_version": None,
                    "right_table_version": None,
                    "issue_type": issue_type,
                    "issue_severity": "FAIL",
                    "key_columns": keys or None,
                    "comparison_mode": "key_based",
                    "comparable_columns": comparable,
                    "ignored_columns": ignored,
                    "sample_only": max_rows is not None,
                    "created_at": now,
                    **kwargs,
                }
            )

        if dup_left and keys:
            for row in left_h.groupBy(*keys).count().filter(F.col("count") > 1).limit(100).collect():
                add_issue(
                    "duplicate_keys_left",
                    key_values_json=row_to_json(row, keys, max_json),
                    left_present=True,
                    right_present=False,
                    left_row_json=None,
                    right_row_json=None,
                    mismatch_columns=None,
                    mismatch_count=None,
                    column_diff_json=None,
                    row_hash=None,
                    left_row_hash=None,
                    right_row_hash=None,
                )

        if dup_right and keys:
            for row in right_h.groupBy(*keys).count().filter(F.col("count") > 1).limit(100).collect():
                add_issue(
                    "duplicate_keys_right",
                    key_values_json=row_to_json(row, keys, max_json),
                    left_present=False,
                    right_present=True,
                    left_row_json=None,
                    right_row_json=None,
                    mismatch_columns=None,
                    mismatch_count=None,
                    column_diff_json=None,
                    row_hash=None,
                    left_row_hash=None,
                    right_row_hash=None,
                )

        missing_df = joined.filter(
            F.col("l.left_row_hash").isNotNull() & F.col("r.right_row_hash").isNull()
        ).select("l.*").limit(max_rows or 100000)
        for row in missing_df.collect():
            add_issue(
                "missing_in_right",
                key_values_json=key_values_json(row, keys, max_json),
                left_present=True,
                right_present=False,
                left_row_json=row_to_json(row, comparable + keys, max_json),
                right_row_json=None,
                left_row_hash=getattr(row, "left_row_hash", None),
                right_row_hash=None,
                row_hash=getattr(row, "left_row_hash", None),
                mismatch_columns=None,
                mismatch_count=None,
                column_diff_json=None,
            )

        extra_df = joined.filter(
            F.col("l.left_row_hash").isNull() & F.col("r.right_row_hash").isNotNull()
        ).select("r.*").limit(max_rows or 100000)
        for row in extra_df.collect():
            add_issue(
                "extra_in_right",
                key_values_json=key_values_json(row, keys, max_json),
                left_present=False,
                right_present=True,
                left_row_json=None,
                right_row_json=row_to_json(row, comparable + keys, max_json),
                left_row_hash=None,
                right_row_hash=getattr(row, "right_row_hash", None),
                row_hash=getattr(row, "right_row_hash", None),
                mismatch_columns=None,
                mismatch_count=None,
                column_diff_json=None,
            )

        mismatch_df = joined.filter(
            F.col("l.left_row_hash").isNotNull()
            & F.col("r.right_row_hash").isNotNull()
            & (F.col("l.left_row_hash") != F.col("r.right_row_hash"))
        ).limit(max_rows or 100000)
        for row in mismatch_df.collect():
            mismatch_cols = [
                c
                for c in comparable
                if str(getattr(row, c, None)) != str(getattr(row, f"r.{c}", getattr(row, c, None)))
            ]
            add_issue(
                "mismatched_rows",
                key_values_json=key_values_json(row, keys, max_json),
                left_present=True,
                right_present=True,
                left_row_hash=getattr(row, "left_row_hash", None),
                right_row_hash=getattr(row, "right_row_hash", None),
                row_hash=getattr(row, "left_row_hash", None),
                left_row_json=row_to_json(row, comparable + keys, max_json),
                right_row_json=row_to_json(row, comparable + keys, max_json),
                mismatch_columns=mismatch_cols or None,
                mismatch_count=len(mismatch_cols) if mismatch_cols else 0,
                column_diff_json=column_diff_json(row, row, mismatch_cols, max_json),
            )

        if not rows:
            return None
        return self.spark.createDataFrame(rows, schema=ROW_ISSUE_SCHEMA)

    def _build_hash_issues(
        self,
        pair: ComparePair,
        context: CompareRunContext,
        joined: DataFrame,
        comparable: list[str],
        ignored: list[str],
        hash_only_left: int,
        hash_only_right: int,
        hash_count_mismatch: int,
    ) -> DataFrame | None:
        if not self.config.row_details.enabled:
            return None
        if not (hash_only_left or hash_only_right or hash_count_mismatch):
            return None

        rows: list[dict[str, Any]] = []
        now = now(timezone.utc)
        max_json = self.config.row_details.max_json_length
        max_rows = self.config.row_details.max_issue_rows_per_table
        label = pair.pair_label()
        run_pair_id = f"{context.dual_run_id}:{label}"

        def add_issue(issue_type: str, **kwargs: Any) -> None:
            if max_rows is not None and len(rows) >= max_rows:
                return
            append(
                {
                    "issue_id": str(uuid.uuid4()),
                    "dual_run_id": context.dual_run_id,
                    "run_pair_id": run_pair_id,
                    "candidate_id": context.candidate_id,
                    "project_name": context.project_name,
                    "table_label": label,
                    "left_ref": pair.left_ref,
                    "right_ref": pair.right_ref,
                    "left_table_version": None,
                    "right_table_version": None,
                    "issue_type": issue_type,
                    "issue_severity": "FAIL",
                    "key_columns": None,
                    "key_values_json": None,
                    "comparison_mode": "hash_based",
                    "comparable_columns": comparable,
                    "ignored_columns": ignored,
                    "sample_only": max_rows is not None,
                    "created_at": now,
                    **kwargs,
                }
            )

        if hash_only_left:
            for row in joined.filter(
                F.col("l.row_hash").isNotNull() & F.col("r.row_hash").isNull()
            ).limit(max_rows or 100000).collect():
                add_issue(
                    "hash_only_left",
                    row_hash=row["row_hash"],
                    left_row_hash=row["row_hash"],
                    right_row_hash=None,
                    left_present=True,
                    right_present=False,
                    left_row_json=json.dumps({"row_hash": row["row_hash"]}, default=str),
                    right_row_json=None,
                    mismatch_columns=None,
                    mismatch_count=None,
                    column_diff_json=None,
                )

        if hash_only_right:
            for row in joined.filter(
                F.col("l.row_hash").isNull() & F.col("r.row_hash").isNotNull()
            ).limit(max_rows or 100000).collect():
                add_issue(
                    "hash_only_right",
                    row_hash=row["row_hash"],
                    left_row_hash=None,
                    right_row_hash=row["row_hash"],
                    left_present=False,
                    right_present=True,
                    left_row_json=None,
                    right_row_json=json.dumps({"row_hash": row["row_hash"]}, default=str),
                    mismatch_columns=None,
                    mismatch_count=None,
                    column_diff_json=None,
                )

        if hash_count_mismatch:
            for row in joined.filter(
                F.col("l.row_hash").isNotNull()
                & F.col("r.row_hash").isNotNull()
                & (F.col("l.left_count") != F.col("r.right_count"))
            ).limit(max_rows or 100000).collect():
                add_issue(
                    "hash_count_mismatch",
                    row_hash=row["row_hash"],
                    left_row_hash=row["row_hash"],
                    right_row_hash=row["row_hash"],
                    left_present=True,
                    right_present=True,
                    left_row_json=json.dumps(
                        {"row_hash": row["row_hash"], "count": row["left_count"]}, default=str
                    ),
                    right_row_json=json.dumps(
                        {"row_hash": row["row_hash"], "count": row["right_count"]}, default=str
                    ),
                    mismatch_columns=None,
                    mismatch_count=None,
                    column_diff_json=None,
                )

        if not rows:
            return None
        return self.spark.createDataFrame(rows, schema=ROW_ISSUE_SCHEMA)
# endregion: row_issues.py

# region: report_sink.py
"""Report artifact writers for dual-run comparison."""






class ReportSink(ABC):
    @abstractmethod
    def write_text(self, path: str, content: str) -> None: ...

    @abstractmethod
    def write_json(self, path: str, payload: dict[str, Any]) -> None: ...

    @abstractmethod
    def write_row_issues(self, path: str, df: DataFrame, config: CompareConfig) -> None: ...


class LocalReportSink(ReportSink):
    def __init__(self, base_dir: Path | None = None):
        self.base_dir = base_dir

    def _resolve(self, path: str) -> Path:
        p = Path(path)
        if p.is_absolute():
            return p
        if self.base_dir:
            return self.base_dir / p
        return p

    def write_text(self, path: str, content: str) -> None:
        target = self._resolve(path)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")

    def write_json(self, path: str, payload: dict[str, Any]) -> None:
        self.write_text(path, json.dumps(payload, indent=2, default=str))

    def write_row_issues(self, path: str, df: DataFrame, config: CompareConfig) -> None:
        target = str(self._resolve(path))
        fmt = config.report.detail_format
        writer = (
            df.write.format(fmt)
            .mode("append")
            .partitionBy("dual_run_id", "table_label", "issue_type")
        )
        if fmt == "delta":
            writer.save(target)
        else:
            writer.save(target)


def write_table_check_artifacts(
    sink: ReportSink,
    paths: ReportPaths,
    table: TableCompareResult,
) -> None:
    sink.write_json(paths.table_summary_path(table.label), {
        "label": table.label,
        "left_ref": table.left_ref,
        "right_ref": table.right_ref,
        "severity": table.severity,
        "table_stats": table.table_stats,
        "row_summary": table.row_summary,
        "delta_stats": table.delta_stats,
        "detail_artifacts": table.detail_artifacts,
    })
    for result in table.check_results:
        sink.write_json(
            paths.table_check_path(table.label, result.check_id),
            {
                "check_id": result.check_id,
                "check_group": result.check_group,
                "severity": result.severity,
                "metrics": result.metrics,
                "message": result.message,
            },
        )
# endregion: report_sink.py

# region: audit.py
"""Audit/index table writers for dual-run comparison."""





def build_report_index_row(report: CompareRunReport, paths: ReportPaths) -> dict[str, Any]:
    counts = report.summary_counts
    artifacts = report.report_artifacts
    return {
        "dual_run_id": report.context.dual_run_id,
        "candidate_id": report.context.candidate_id,
        "project_name": report.context.project_name,
        "overall_severity": report.overall_severity,
        "compared_tables": counts.get("compared_tables", 0),
        "passed_tables": counts.get("passed_tables", 0),
        "failed_tables": counts.get("failed_tables", 0),
        "warn_tables": counts.get("warn_tables", 0),
        "blocked_tables": counts.get("blocked_tables", 0),
        "total_row_issues": counts.get("total_row_issues", 0),
        "report_root": paths.run_root,
        "summary_json_path": artifacts.get("summary_json", paths.summary_json_path),
        "summary_markdown_path": artifacts.get("summary_markdown", paths.summary_markdown_path),
        "summary_html_path": artifacts.get("summary_html", paths.summary_html_path),
        "row_issues_path": artifacts.get("row_issues", {}).get("path", paths.row_issues_path),
        "created_at": report.context.created_at or now(timezone.utc).isoformat(),
    }


def build_table_result_rows(
    report: CompareRunReport,
    paths: ReportPaths,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for table in report.table_results:
        row_summary = table.row_summary or {}
        append(
            {
                "dual_run_id": report.context.dual_run_id,
                "candidate_id": report.context.candidate_id,
                "project_name": report.context.project_name,
                "table_label": table.label,
                "left_ref": table.left_ref,
                "right_ref": table.right_ref,
                "table_severity": table.severity,
                "row_count_status": _status_for_check(table, "row_count"),
                "schema_status": _status_for_check(table, "schema_equality"),
                "row_compare_status": _status_for_check(table, "key_based")
                or _status_for_check(table, "hash_based"),
                "delta_ops_status": _status_for_check(table, "metrics"),
                "delta_version_status": _status_for_check(table, "stats"),
                "matched_rows": row_summary.get("matched_rows"),
                "mismatched_rows": row_summary.get("mismatched_rows"),
                "missing_in_right": row_summary.get("missing_in_right"),
                "extra_in_right": row_summary.get("extra_in_right"),
                "duplicate_keys_left": row_summary.get("duplicate_keys_left"),
                "duplicate_keys_right": row_summary.get("duplicate_keys_right"),
                "row_issues_count": row_summary.get("row_issues_count", 0),
                "row_issues_path": table.detail_artifacts.get("row_issues", {}).get(
                    "path", paths.row_issues_path
                ),
                "table_summary_json_path": paths.table_summary_path(table.label),
                "created_at": report.context.created_at or now(timezone.utc).isoformat(),
            }
        )
    return rows


def build_check_result_rows(report: CompareRunReport, paths: ReportPaths) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for table in report.table_results:
        for result in table.check_results:
            append(
                {
                    "dual_run_id": report.context.dual_run_id,
                    "candidate_id": report.context.candidate_id,
                    "project_name": report.context.project_name,
                    "table_label": table.label,
                    "check_id": result.check_id,
                    "check_group": result.check_group,
                    "severity": result.severity,
                    "metrics_json": json.dumps(result.metrics, default=str),
                    "detail_path": paths.table_check_path(table.label, result.check_id),
                    "created_at": report.context.created_at or now(timezone.utc).isoformat(),
                }
            )
    return rows


def _status_for_check(table: TableCompareResult, check_id: str) -> str | None:
    for result in table.check_results:
        if result.check_id == check_id:
            return result.severity
    return None


def write_audit_tables(
    spark,
    report: CompareRunReport,
    paths: ReportPaths,
    config: CompareConfig,
) -> None:
    if not config.report.write_audit_tables:
        return
    catalog = config.report.audit_catalog
    schema = config.report.audit_schema
    index_table = f"{catalog}.{schema}.dual_run_report_index"
    table_results = f"{catalog}.{schema}.dual_run_table_results"
    check_results = f"{catalog}.{schema}.dual_run_check_results"

    index_df = spark.createDataFrame([build_report_index_row(report, paths)])
    table_df = spark.createDataFrame(build_table_result_rows(report, paths))
    check_df = spark.createDataFrame(build_check_result_rows(report, paths))

    index_df.write.format("delta").mode("append").saveAsTable(index_table)
    table_df.write.format("delta").mode("append").saveAsTable(table_results)
    check_df.write.format("delta").mode("append").saveAsTable(check_results)
# endregion: audit.py

# region: executor.py
"""Main runtime executor for dual-run comparison."""






class DualRunComparatorExecutor:
    def __init__(
        self,
        spark: SparkSession,
        config: CompareConfig,
        report_sink: ReportSink | None = None,
    ):
        self.spark = spark
        self.config = config
        self.report_sink = report_sink or LocalReportSink()

    def execute(
        self,
        context: CompareRunContext,
        pairs: list[ComparePair],
    ) -> CompareRunReport:
        if not context.created_at:
            context.created_at = now(timezone.utc).isoformat()

        paths = resolve_report_paths(context)
        table_results: list[TableCompareResult] = []
        all_row_issues: list[DataFrame] = []

        for pair in pairs:
            check_results, row_issues = execute_checks_for_pair(
                self.spark, pair, self.config, context
            )
            if row_issues is not None:
                all_row_issues.append(row_issues)

            table_stats, row_summary, delta_stats = _partition_results(check_results)
            severity = rollup_severity(check_results)
            detail_artifacts = {
                "row_issues": {
                    "path": paths.row_issues_path,
                    "format": self.config.report.detail_format,
                    "partition_columns": ["dual_run_id", "table_label", "issue_type"],
                    "filter": paths.row_issues_filter(pair.pair_label(), context.dual_run_id),
                }
            }
            table = TableCompareResult(
                label=pair.pair_label(),
                left_ref=pair.left_ref,
                right_ref=pair.right_ref,
                severity=severity,
                check_results=check_results,
                table_stats=table_stats,
                row_summary=row_summary,
                delta_stats=delta_stats,
                detail_artifacts=detail_artifacts,
            )
            table_results.append(table)
            write_table_check_artifacts(self.report_sink, paths, table)

        if all_row_issues:
            combined = all_row_issues[0]
            for df in all_row_issues[1:]:
                combined = combined.unionByName(df, allowMissingColumns=True)
            self.report_sink.write_row_issues(paths.row_issues_path, combined, self.config)

        summary_counts = _summary_counts(table_results)
        overall = rollup_severity(
            [r for t in table_results for r in t.check_results]
        )
        report_artifacts = {
            "summary_json": paths.summary_json_path,
            "summary_markdown": paths.summary_markdown_path,
            "summary_html": paths.summary_html_path,
            "row_issues": {
                "path": paths.row_issues_path,
                "format": self.config.report.detail_format,
                "issue_type_column": "issue_type",
            },
        }

        report = CompareRunReport(
            context=context,
            overall_severity=overall,
            summary_counts=summary_counts,
            table_results=table_results,
            report_artifacts=report_artifacts,
        )

        if self.config.report.summary_json:
            self.report_sink.write_text(paths.summary_json_path, render_summary_json(report))
        if self.config.report.summary_markdown:
            self.report_sink.write_text(paths.summary_markdown_path, render_summary_markdown(report))
        if self.config.report.summary_html:
            self.report_sink.write_text(paths.summary_html_path, render_summary_html(report))

        self.report_sink.write_json(paths.compare_manifest_path, _manifest_payload(context, pairs))
        self.report_sink.write_json(paths.compare_config_path, _config_payload(self.config))

        try:
            write_audit_tables(self.spark, report, paths, self.config)
        except Exception:
            pass

        return report

    def should_fail_process(self, report: CompareRunReport) -> bool:
        return report.overall_severity in self.config.runtime.fail_process_on


def _partition_results(
    check_results: list[CheckResult],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    table_stats: dict[str, Any] = {
        "basic": {},
        "nulls": {},
        "distinct": {},
        "numeric": {},
        "datetime": {},
        "distribution": {},
    }
    row_summary: dict[str, Any] = {}
    delta_stats: dict[str, Any] = {"operation_metrics": {}, "version_stats": {}}

    for result in check_results:
        group = result.check_group
        if group in table_stats:
            table_stats[group][result.check_id.split(".", 1)[-1]] = result.metrics
        if result.check_id in ("key_based", "hash_based"):
            row_summary = result.metrics
        if result.check_id == "metrics":
            delta_stats["operation_metrics"] = result.metrics
        if result.check_id == "stats":
            delta_stats["version_stats"] = result.metrics
    return table_stats, row_summary, delta_stats


def _summary_counts(table_results: list[TableCompareResult]) -> dict[str, int]:
    passed = failed = warn = blocked = 0
    total_issues = 0
    for table in table_results:
        total_issues += int((table.row_summary or {}).get("row_issues_count", 0))
        if table.severity == "PASS":
            passed += 1
        elif table.severity == "FAIL":
            failed += 1
        elif table.severity == "WARN":
            warn += 1
        elif table.severity == "BLOCKED":
            blocked += 1
    return {
        "compared_tables": len(table_results),
        "passed_tables": passed,
        "failed_tables": failed,
        "warn_tables": warn,
        "blocked_tables": blocked,
        "total_row_issues": total_issues,
    }


def _manifest_payload(context: CompareRunContext, pairs: list[ComparePair]) -> dict[str, Any]:

    return {
        "dual_run_id": context.dual_run_id,
        "candidate_id": context.candidate_id,
        "project_name": context.project_name,
        "report_root": context.report_root,
        "pairs": [pair_to_dict(p) for p in pairs],
    }


def _config_payload(config: CompareConfig) -> dict[str, Any]:

    return config_to_dict(config)
# endregion: executor.py

# region: entrypoint
def _pair_from_emitted(data: dict) -> ComparePair:
    return ComparePair(
        left_ref=str(data["left_ref"]),
        right_ref=str(data["right_ref"]),
        label=data.get("label"),
        key_columns=data.get("key_columns"),
        partition_columns=data.get("partition_columns"),
        comparable_columns=data.get("comparable_columns"),
        numeric_columns=data.get("numeric_columns"),
        date_columns=data.get("date_columns"),
        timestamp_columns=data.get("timestamp_columns"),
        status_column=data.get("status_column"),
        ignored_columns=data.get("ignored_columns"),
    )


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Execute dual-run output comparison")
    parser.add_argument("--dual-run-id", required=True)
    parser.add_argument("--candidate-id", required=True)
    parser.add_argument("--project-name", required=True)
    parser.add_argument("--report-root", default=EMITTED_DEFAULT_REPORT_ROOT)
    args = parser.parse_args(argv)

    pairs = [_pair_from_emitted(item) for item in EMITTED_COMPARE_PAIRS]
    config = compare_config_from_dict(EMITTED_COMPARE_CONFIG)

    from pyspark.sql import SparkSession

    spark = SparkSession.builder.appName(f"dual-run-compare-{args.dual_run_id}").getOrCreate()
    context = CompareRunContext(
        dual_run_id=args.dual_run_id,
        candidate_id=args.candidate_id,
        project_name=args.project_name,
        report_root=args.report_root,
    )
    sink = LocalReportSink()
    executor = DualRunComparatorExecutor(spark=spark, config=config, report_sink=sink)
    report = executor.execute(context, pairs)
    if executor.should_fail_process(report):
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
# endregion: entrypoint
